//! Which TimeScale, System and Unit settings a TimeFrame rejects, and the
//! TimeOrigin that results otherwise, checked against the C library.
//!
//! `time_scale_set_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/time_scale_set_probe.c`. C's SetTimeScale rejects
//! a timescale other than TT on a BEPOCH TimeFrame with AST__ATTIN, and
//! re-expresses the TimeOrigin in the new timescale; SetSystem to BEPOCH
//! first sets Unit to "yr" and TimeScale to TT; SetUnit on a BEPOCH
//! TimeFrame rejects any Unit but "yr" (timeframe.c SetTimeScale,
//! ClearTimeScale, OriginScale, SetSystem, SetUnit).

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "time_scale_set_oracle/cases.rs"]
mod cases;

use starlink_ast::error::{AstResult, ErrorCode};
use starlink_ast::frames::{Frame, TimeFrame, TimeScale, TimeSystem};

fn step(f: &mut TimeFrame, step: &str) -> AstResult<()> {
    if step == "clear" {
        return f.clear_timescale();
    }
    match step.split_once('=').unwrap() {
        ("TimeScale", v) => f.set_timescale(TimeScale::parse(v).unwrap()),
        ("System", v) => f.set_system(TimeSystem::parse(v).unwrap()),
        ("Unit(1)", v) => Frame::set_unit(f, 1, v),
        other => panic!("no Rust set-up for {other:?}"),
    }
}

fn run(from: &str, action: &str) -> Result<(String, String, String, f64), String> {
    let mut f = TimeFrame::new(TimeSystem::Mjd);
    f.set_timescale(TimeScale::parse(from).unwrap()).unwrap();
    f.set_time_origin_cur(55000.5).unwrap();
    for s in action.split(';') {
        if let Err(e) = step(&mut f, s) {
            return Err(match e.code() {
                ErrorCode::Attin => "Attin".into(),
                ErrorCode::Incts => "Incts".into(),
                code => format!("{code:?}"),
            });
        }
    }
    Ok((
        f.system().as_str().to_string(),
        f.timescale().as_str().to_string(),
        Frame::unit(&f, 1).unwrap(),
        f.time_origin_cur(),
    ))
}

#[test]
fn timescale_settings_match_the_c_library() {
    let mut failures = Vec::new();
    for &(from, action, want) in cases::CASES {
        let got = run(from, action);
        let want = want
            .map(|(s, t, u, o)| (s.to_string(), t.to_string(), u.to_string(), o))
            .map_err(str::to_string);
        if got != want {
            failures.push(format!("{from} [{action}]: got {got:?}, C gives {want:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from C:\n{}",
        failures.len(),
        cases::CASES.len(),
        failures.join("\n")
    );
}
